const queuePrune = `-- name: QueuePrune :execrows
DELETE FROM operations
WHERE status IN ('completed', 'failed', 'cancelled') AND finished_at < $1::timestamptz
`

// QueuePrune deletes terminal operations finished before the cutoff.
func (q *Queries) QueuePrune(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, queuePrune, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

